                    byte_hops = L * (4 + f.dcount + plen)
                else:
                    wire = []
                    byte_hops = 0
                if L == N:
                    xi = ((int.from_bytes(hdr, 'big') & f.zmask & f.tclear)
                          | ((t0 - N + 1) << f.tshift))
                    delivered = xi.to_bytes(f.H, 'big').hex() + pay_hex
                else:
